// API Service Layer for FBR Invoice Portal

// Configuration
const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL || 'http://localhost:8000/api';
const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL || 'http://localhost:8000';

// Base API client
class ApiClient {
  protected baseUrl: string;

  constructor() {
    this.baseUrl = API_BASE_URL;
  }

  // Helper method to make API requests
  protected async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = `${this.baseUrl}${endpoint}`;

    const config: RequestInit = {
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
      ...options,
    };

    // Add auth token if available
    const token = this.getAuthToken();
    if (token && !endpoint.startsWith('/auth')) {
      (config.headers as Record<string, string>)['Authorization'] = `Bearer ${token}`;
    }

    const response = await fetch(url, config);

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP error! status: ${response.status}`);
    }

    // Some endpoints may not return JSON (e.g., PDF downloads)
    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      return await response.json();
    }

    return {} as T;
  }

  protected getAuthToken(): string | null {
    // In a real app, you'd get this from a secure store
    // For now, we'll use localStorage as a placeholder
    if (typeof window !== 'undefined') {
      return localStorage.getItem('auth_token');
    }
    return null;
  }

  // Set auth token
  public setAuthToken(token: string): void {
    if (typeof window !== 'undefined') {
      localStorage.setItem('auth_token', token);
    }
  }

  // Remove auth token
  public removeAuthToken(): void {
    if (typeof window !== 'undefined') {
      localStorage.removeItem('auth_token');
    }
  }
}

// Specific service classes extending ApiClient
export class AuthService extends ApiClient {
  async login(email: string, password: string): Promise<{ user: any; token: string }> {
    return this.request('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
  }

  async register(userData: { email: string; password: string; name: string }): Promise<{ user: any }> {
    return this.request('/auth/register', {
      method: 'POST',
      body: JSON.stringify(userData),
    });
  }

  async logout(): Promise<void> {
    await this.request('/auth/logout', {
      method: 'POST',
    });
    this.removeAuthToken();
  }

  async getCurrentUser(): Promise<any> {
    return this.request('/users/me');
  }
}

export class InvoiceService extends ApiClient {
  async getInvoices(params?: {
    page?: number;
    limit?: number;
    status?: string;
    type?: string;
    search?: string;
    startDate?: string;
    endDate?: string;
    environment?: string;
  }): Promise<{ invoices: any[]; pagination: any }> {
    const queryParams = new URLSearchParams();
    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined) {
          queryParams.append(key, String(value));
        }
      });
    }

    const queryString = queryParams.toString();
    const endpoint = `/invoices${queryString ? '?' + queryString : ''}`;

    return this.request(endpoint);
  }

  async createInvoice(invoiceData: any): Promise<{ success: boolean; invoice: any }> {
    return this.request('/invoices', {
      method: 'POST',
      body: JSON.stringify(invoiceData),
    });
  }

  async updateInvoice(id: string, invoiceData: any): Promise<{ success: boolean; invoice: any }> {
    return this.request(`/invoices/${id}`, {
      method: 'PUT',
      body: JSON.stringify(invoiceData),
    });
  }

  async validateInvoice(id: string): Promise<{ success: boolean; invoice: any }> {
    return this.request(`/invoices/${id}/validate`, {
      method: 'POST',
    });
  }

  async postInvoice(id: string): Promise<{ success: boolean; invoice: any }> {
    return this.request(`/invoices/${id}/post`, {
      method: 'POST',
    });
  }

  async bulkPostInvoices(invoiceIds: string[]): Promise<{ success: boolean; results: any[] }> {
    return this.request('/invoices/bulk-post', {
      method: 'POST',
      body: JSON.stringify({ invoiceIds }),
    });
  }

  async getInvoicePdf(id: string): Promise<Blob> {
    const url = `${this.baseUrl}/invoices/${id}/pdf`;
    const token = this.getAuthToken();

    const response = await fetch(url, {
      headers: {
        ...(token && { 'Authorization': `Bearer ${token}` }),
      },
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP error! status: ${response.status}`);
    }

    return await response.blob();
  }
}

export class UserService extends ApiClient {
  async getCurrentUser(): Promise<any> {
    return this.request('/users/me');
  }

  async updateEnvironmentPreference(environment: 'sandbox' | 'production'): Promise<{ success: boolean; environment: string; canAccessProduction: boolean }> {
    return this.request('/users/me/environment', {
      method: 'PUT',
      body: JSON.stringify({ environment }),
    });
  }

  async getEnvironmentPreference(): Promise<{ environment: string; canAccessProduction: boolean }> {
    return this.request('/users/me/environment');
  }
}

// Export singleton instances
export const authService = new AuthService();
export const invoiceService = new InvoiceService();
export const userService = new UserService();