'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Trash2, Plus } from 'lucide-react';

interface InvoiceItem {
  hsCode: string;
  productDescription: string;
  rate: string;
  uoM: string;
  quantity: number;
  totalValues: number;
  valueSalesExcludingST: number;
  fixedNotifiedValueOrRetailPrice: number;
  salesTaxApplicable: number;
  salesTaxWithheldAtSource: number;
  extraTax: number;
  furtherTax: number;
  sroScheduleNo: string;
  fedPayable: number;
  discount: number;
  saleType: string;
  sroItemSerialNo: string;
}

interface SaleInvoiceFormProps {
  onSubmit: (data: any) => void;
  onCancel: () => void;
  isLoading: boolean;
}

const PROVINCES = ['Punjab', 'Sindh', 'Khyber Pakhtunkhwa', 'Balochistan', 'Islamabad Capital Territory', 'Gilgit-Baltistan', 'Azad Jammu and Kashmir'];
const TAX_RATES = ['0%', '1%', '5%', '10%', '12%', '15%', '17%', '18%'];
const SALE_TYPES = ['Goods at standard rate (default)', 'Goods at reduced rate', 'Goods at zero rate', 'Exempt goods', 'Services'];

export function SaleInvoiceForm({ onSubmit, onCancel, isLoading }: SaleInvoiceFormProps) {
  // Invoice header state
  const [invoiceType, setInvoiceType] = useState<'Sale Invoice' | 'Debit Note'>('Sale Invoice');
  const [invoiceDate, setInvoiceDate] = useState('');
  const [invoiceRefNo, setInvoiceRefNo] = useState('');
  const [scenarioId, setScenarioId] = useState('');
  const [environment, setEnvironment] = useState<'SANDBOX' | 'PRODUCTION'>('SANDBOX');

  // Seller information state
  const [sellerNTNCNIC, setSellerNTNCNIC] = useState('');
  const [sellerBusinessName, setSellerBusinessName] = useState('');
  const [sellerProvince, setSellerProvince] = useState('');
  const [sellerAddress, setSellerAddress] = useState('');

  // Buyer information state
  const [buyerNTNCNIC, setBuyerNTNCNIC] = useState('');
  const [buyerBusinessName, setBuyerBusinessName] = useState('');
  const [buyerProvince, setBuyerProvince] = useState('');
  const [buyerAddress, setBuyerAddress] = useState('');
  const [buyerRegistrationType, setBuyerRegistrationType] = useState<'Registered' | 'Unregistered'>('Registered');

  // Invoice items state
  const [items, setItems] = useState<InvoiceItem[]>([{
    hsCode: '',
    productDescription: '',
    rate: '18%',
    uoM: 'Numbers, pieces, units',
    quantity: 1,
    totalValues: 0,
    valueSalesExcludingST: 0,
    fixedNotifiedValueOrRetailPrice: 0,
    salesTaxApplicable: 0,
    salesTaxWithheldAtSource: 0,
    extraTax: 0,
    furtherTax: 0,
    sroScheduleNo: '',
    fedPayable: 0,
    discount: 0,
    saleType: 'Goods at standard rate (default)',
    sroItemSerialNo: ''
  }]);

  const addItem = () => {
    setItems([...items, {
      hsCode: '',
      productDescription: '',
      rate: '18%',
      uoM: 'Numbers, pieces, units',
      quantity: 1,
      totalValues: 0,
      valueSalesExcludingST: 0,
      fixedNotifiedValueOrRetailPrice: 0,
      salesTaxApplicable: 0,
      salesTaxWithheldAtSource: 0,
      extraTax: 0,
      furtherTax: 0,
      sroScheduleNo: '',
      fedPayable: 0,
      discount: 0,
      saleType: 'Goods at standard rate (default)',
      sroItemSerialNo: ''
    }]);
  };

  const removeItem = (index: number) => {
    if (items.length > 1) {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const updateItem = (index: number, field: keyof InvoiceItem, value: any) => {
    const updatedItems = [...items];
    updatedItems[index] = { ...updatedItems[index], [field]: value };
    setItems(updatedItems);
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const invoiceData = {
      invoice_type: invoiceType,
      invoice_date: invoiceDate,
      seller_ntn_cnic: sellerNTNCNIC,
      seller_business_name: sellerBusinessName,
      seller_province: sellerProvince,
      seller_address: sellerAddress,
      buyer_ntn_cnic: buyerNTNCNIC,
      buyer_business_name: buyerBusinessName,
      buyer_province: buyerProvince,
      buyer_address: buyerAddress,
      buyer_registration_type: buyerRegistrationType,
      invoice_ref_no: invoiceRefNo || undefined,
      scenario_id: scenarioId || undefined,
      items: items,
      environment: environment
    };

    onSubmit(invoiceData);
  };

  return (
    <form onSubmit={handleFormSubmit} className="space-y-6">
      {/* Invoice Header */}
      <Card>
        <CardHeader>
          <CardTitle>Invoice Information</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <Label htmlFor="invoiceType">Invoice Type *</Label>
              <Select value={invoiceType} onValueChange={(val) => setInvoiceType(val as 'Sale Invoice' | 'Debit Note')}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Sale Invoice">Sale Invoice</SelectItem>
                  <SelectItem value="Debit Note">Debit Note</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="invoiceDate">Invoice Date *</Label>
              <Input
                id="invoiceDate"
                type="date"
                value={invoiceDate}
                onChange={(e) => setInvoiceDate(e.target.value)}
                required
              />
            </div>

            <div>
              <Label htmlFor="environment">Environment *</Label>
              <Select value={environment} onValueChange={(val) => setEnvironment(val as 'SANDBOX' | 'PRODUCTION')}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="SANDBOX">Sandbox</SelectItem>
                  <SelectItem value="PRODUCTION">Production</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {invoiceType === 'Debit Note' && (
            <div>
              <Label htmlFor="invoiceRefNo">Invoice Reference Number *</Label>
              <Input
                id="invoiceRefNo"
                value={invoiceRefNo}
                onChange={(e) => setInvoiceRefNo(e.target.value)}
                placeholder="Reference invoice number (22 or 28 digits)"
                required
              />
              <p className="text-xs text-gray-500 mt-1">22 digits for NTN, 28 digits for CNIC</p>
            </div>
          )}

          {environment === 'SANDBOX' && (
            <div>
              <Label htmlFor="scenarioId">Scenario ID</Label>
              <Input
                id="scenarioId"
                value={scenarioId}
                onChange={(e) => setScenarioId(e.target.value)}
                placeholder="e.g., SN001"
              />
              <p className="text-xs text-gray-500 mt-1">Required for sandbox testing</p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Seller Information */}
      <Card>
        <CardHeader>
          <CardTitle>Seller Information</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="sellerNTNCNIC">Seller NTN/CNIC *</Label>
              <Input
                id="sellerNTNCNIC"
                value={sellerNTNCNIC}
                onChange={(e) => setSellerNTNCNIC(e.target.value)}
                placeholder="Enter NTN or CNIC"
                required
              />
            </div>

            <div>
              <Label htmlFor="sellerBusinessName">Business Name *</Label>
              <Input
                id="sellerBusinessName"
                value={sellerBusinessName}
                onChange={(e) => setSellerBusinessName(e.target.value)}
                placeholder="Enter business name"
                required
              />
            </div>

            <div>
              <Label htmlFor="sellerProvince">Province *</Label>
              <Select value={sellerProvince} onValueChange={setSellerProvince}>
                <SelectTrigger>
                  <SelectValue placeholder="Select province" />
                </SelectTrigger>
                <SelectContent>
                  {PROVINCES.map((province) => (
                    <SelectItem key={province} value={province}>{province}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="sellerAddress">Address *</Label>
              <Input
                id="sellerAddress"
                value={sellerAddress}
                onChange={(e) => setSellerAddress(e.target.value)}
                placeholder="Enter business address"
                required
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Buyer Information */}
      <Card>
        <CardHeader>
          <CardTitle>Buyer Information</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="buyerRegistrationType">Registration Type *</Label>
              <Select value={buyerRegistrationType} onValueChange={(val) => setBuyerRegistrationType(val as 'Registered' | 'Unregistered')}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Registered">Registered</SelectItem>
                  <SelectItem value="Unregistered">Unregistered</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="buyerNTNCNIC">
                Buyer NTN/CNIC {buyerRegistrationType === 'Registered' ? '*' : '(Optional)'}
              </Label>
              <Input
                id="buyerNTNCNIC"
                value={buyerNTNCNIC}
                onChange={(e) => setBuyerNTNCNIC(e.target.value)}
                placeholder="Enter NTN or CNIC"
                required={buyerRegistrationType === 'Registered'}
              />
            </div>

            <div>
              <Label htmlFor="buyerBusinessName">Business Name *</Label>
              <Input
                id="buyerBusinessName"
                value={buyerBusinessName}
                onChange={(e) => setBuyerBusinessName(e.target.value)}
                placeholder="Enter business name"
                required
              />
            </div>

            <div>
              <Label htmlFor="buyerProvince">Province *</Label>
              <Select value={buyerProvince} onValueChange={setBuyerProvince}>
                <SelectTrigger>
                  <SelectValue placeholder="Select province" />
                </SelectTrigger>
                <SelectContent>
                  {PROVINCES.map((province) => (
                    <SelectItem key={province} value={province}>{province}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="md:col-span-2">
              <Label htmlFor="buyerAddress">Address *</Label>
              <Input
                id="buyerAddress"
                value={buyerAddress}
                onChange={(e) => setBuyerAddress(e.target.value)}
                placeholder="Enter business address"
                required
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Invoice Items */}
      <Card>
        <CardHeader>
          <div className="flex justify-between items-center">
            <CardTitle>Invoice Items</CardTitle>
            <Button type="button" variant="outline" size="sm" onClick={addItem}>
              <Plus className="h-4 w-4 mr-2" />
              Add Item
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          {items.map((item, index) => (
            <div key={index} className="border rounded-lg p-4 space-y-4">
              <div className="flex justify-between items-center mb-2">
                <h4 className="font-medium">Item {index + 1}</h4>
                {items.length > 1 && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => removeItem(index)}
                  >
                    <Trash2 className="h-4 w-4 text-red-500" />
                  </Button>
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <Label>HS Code *</Label>
                  <Input
                    value={item.hsCode}
                    onChange={(e) => updateItem(index, 'hsCode', e.target.value)}
                    placeholder="e.g., 0101.2100"
                    required
                  />
                </div>

                <div className="md:col-span-2">
                  <Label>Product Description *</Label>
                  <Input
                    value={item.productDescription}
                    onChange={(e) => updateItem(index, 'productDescription', e.target.value)}
                    placeholder="Details of product or service"
                    required
                  />
                </div>

                <div>
                  <Label>Tax Rate *</Label>
                  <Select value={item.rate} onValueChange={(val) => updateItem(index, 'rate', val)}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {TAX_RATES.map((rate) => (
                        <SelectItem key={rate} value={rate}>{rate}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>Unit of Measurement *</Label>
                  <Input
                    value={item.uoM}
                    onChange={(e) => updateItem(index, 'uoM', e.target.value)}
                    placeholder="e.g., Numbers, pieces, units"
                    required
                  />
                </div>

                <div>
                  <Label>Quantity *</Label>
                  <Input
                    type="number"
                    step="0.0001"
                    value={item.quantity}
                    onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Total Value (Inc. Tax) *</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.totalValues}
                    onChange={(e) => updateItem(index, 'totalValues', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Value Excl. Sales Tax *</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.valueSalesExcludingST}
                    onChange={(e) => updateItem(index, 'valueSalesExcludingST', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Fixed/Retail Price *</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.fixedNotifiedValueOrRetailPrice}
                    onChange={(e) => updateItem(index, 'fixedNotifiedValueOrRetailPrice', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Sales Tax Applicable *</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.salesTaxApplicable}
                    onChange={(e) => updateItem(index, 'salesTaxApplicable', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Sales Tax Withheld *</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.salesTaxWithheldAtSource}
                    onChange={(e) => updateItem(index, 'salesTaxWithheldAtSource', parseFloat(e.target.value) || 0)}
                    required
                  />
                </div>

                <div>
                  <Label>Extra Tax</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.extraTax}
                    onChange={(e) => updateItem(index, 'extraTax', parseFloat(e.target.value) || 0)}
                  />
                </div>

                <div>
                  <Label>Further Tax</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.furtherTax}
                    onChange={(e) => updateItem(index, 'furtherTax', parseFloat(e.target.value) || 0)}
                  />
                </div>

                <div>
                  <Label>SRO Schedule No</Label>
                  <Input
                    value={item.sroScheduleNo}
                    onChange={(e) => updateItem(index, 'sroScheduleNo', e.target.value)}
                    placeholder="e.g., SRO123"
                  />
                </div>

                <div>
                  <Label>FED Payable</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.fedPayable}
                    onChange={(e) => updateItem(index, 'fedPayable', parseFloat(e.target.value) || 0)}
                  />
                </div>

                <div>
                  <Label>Discount</Label>
                  <Input
                    type="number"
                    step="0.01"
                    value={item.discount}
                    onChange={(e) => updateItem(index, 'discount', parseFloat(e.target.value) || 0)}
                  />
                </div>

                <div>
                  <Label>Sale Type *</Label>
                  <Select value={item.saleType} onValueChange={(val) => updateItem(index, 'saleType', val)}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {SALE_TYPES.map((type) => (
                        <SelectItem key={type} value={type}>{type}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>SRO Item Serial No</Label>
                  <Input
                    value={item.sroItemSerialNo}
                    onChange={(e) => updateItem(index, 'sroItemSerialNo', e.target.value)}
                    placeholder="Optional"
                  />
                </div>
              </div>
            </div>
          ))}
        </CardContent>
      </Card>

      {/* Form Actions */}
      <div className="flex justify-between">
        <Button type="button" variant="outline" onClick={onCancel} disabled={isLoading}>
          Cancel
        </Button>
        <Button type="submit" disabled={isLoading}>
          {isLoading ? 'Creating Invoice...' : 'Create Invoice'}
        </Button>
      </div>
    </form>
  );
}